#!/usr/bin/env python3
"""Durability and recovery helpers for the replicated key-value store."""

import os
import tempfile


def fsync_directory(path):
    """Persist directory-entry changes made in *path*."""
    flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    fd = os.open(path or ".", flags)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def load_int(path):
    if not os.path.exists(path):
        return -1
    with open(path, encoding="ascii") as f:
        text = f.read().strip()
    return int(text) if text else -1


def save_int(path, value):
    """Atomically and durably store a non-negative checkpoint integer."""
    value = int(value)
    directory = os.path.dirname(path) or "."
    os.makedirs(directory, exist_ok=True)
    payload = (str(value) + "\n").encode("ascii")
    fd = None
    temporary = None
    try:
        fd, temporary = tempfile.mkstemp(
            prefix="." + os.path.basename(path) + ".",
            suffix=".tmp",
            dir=directory,
        )
        with os.fdopen(fd, "wb") as f:
            fd = None
            f.write(payload)
            f.flush()
            os.fsync(f.fileno())
        os.replace(temporary, path)
        temporary = None
        fsync_directory(directory)
    finally:
        if fd is not None:
            os.close(fd)
        if temporary is not None and os.path.exists(temporary):
            os.unlink(temporary)


def load_manifest(path):
    """Load the persisted sync point."""
    return load_int(path)


def save_manifest(path, idx):
    """Persist the sync point without a torn update."""
    save_int(path, idx)


def get_replay_target(ack_index, manifest_path):
    """Return the highest valid durable checkpoint.

    Both files are written with atomic replacement.  Taking the maximum is
    safe: a checkpoint can only be ahead of an acknowledgement in the narrow
    crash window before its response reaches the client.
    """
    manifest_index = load_manifest(manifest_path)
    return max(ack_index if ack_index is not None else -1,
               manifest_index if manifest_index is not None else -1)


def on_promote(state, ack_index):
    """Apply the follower's durable WAL when it is promoted to leader."""
    target = max(ack_index if ack_index is not None else -1,
                 state.wal.last_index)
    if target >= 0:
        state.apply_through(target)
    return target
