#!/usr/bin/env python3
"""Replicated key-value store with durable WAL and leader/follower roles."""

import asyncio
import json
import os
import sys
import tempfile

import recovery

DATA_DIR = "/app/data"


def _fsync_directory(path):
    recovery.fsync_directory(path)


class WAL:
    """Write-ahead log with contiguous indexes and durable appends."""

    def __init__(self, path):
        self.path = path
        self.entries = []
        os.makedirs(os.path.dirname(path), exist_ok=True)
        created = not os.path.exists(path)
        if created:
            with open(path, "ab"):
                pass
            _fsync_directory(os.path.dirname(path) or ".")
        self._load()

    def _load(self):
        try:
            with open(self.path, "rb") as f:
                raw = f.read()
        except FileNotFoundError:
            return

        if not raw:
            return

        # A process can be killed while writing an unacknowledged tail.  Keep
        # every complete, valid record and discard only a torn final record.
        final_newline = raw.rfind(b"\n")
        usable = raw[:final_newline + 1] if final_newline >= 0 else b""
        entries = []
        for line in usable.splitlines():
            if not line:
                continue
            try:
                entries.append(json.loads(line.decode("utf-8")))
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise ValueError(f"corrupt WAL record in {self.path}") from exc

        if len(usable) != len(raw):
            with open(self.path, "r+b") as f:
                f.truncate(len(usable))
                f.flush()
                os.fsync(f.fileno())
        self.entries = entries

    def append(self, entry):
        """Durably append one entry and return its log index."""
        payload = (json.dumps(entry, separators=(",", ":")) + "\n").encode("utf-8")
        original_size = os.path.getsize(self.path)
        try:
            with open(self.path, "ab") as f:
                f.write(payload)
                f.flush()
                os.fsync(f.fileno())
        except Exception:
            # Never leave a failed append visible in memory.  Also restore the
            # byte length so a later append does not embed a torn record.
            try:
                with open(self.path, "r+b") as f:
                    f.truncate(original_size)
                    f.flush()
                    os.fsync(f.fileno())
            except Exception:
                pass
            raise
        self.entries.append(entry)
        return len(self.entries) - 1

    @property
    def last_index(self):
        return len(self.entries) - 1 if self.entries else -1


class KVState:
    """Key-value state machine with apply tracking."""

    def __init__(self, wal_path):
        self.wal = WAL(wal_path)
        self.data = {}
        self.applied_up_to = -1

