        op = entry.get("op")
        if op == "SET":
            self.data[entry["key"]] = entry["value"]
        elif op == "DEL":
            self.data.pop(entry["key"], None)

    def apply_through(self, index):
        index = int(index)
        if index < self.applied_up_to:
            return
        if index >= len(self.wal.entries):
            raise IndexError("replay index exceeds durable WAL")
        while self.applied_up_to < index:
            self.applied_up_to += 1
            self._apply(self.wal.entries[self.applied_up_to])

    def get(self, key):
        return self.data.get(key)

    def propose(self, op, key, value=None):
        entry = {"op": op, "key": key}
        if value is not None:
            entry["value"] = value
        return self.wal.append(entry)


def _load_mark(path):
    if not os.path.exists(path):
        return -1
    with open(path, encoding="ascii") as f:
        text = f.read().strip()
    return int(text) if text else -1


def _save_mark(path, idx):
    recovery.save_int(path, idx)


class ReplicatedKV:
    """Server handling client requests and single-follower replication."""

    def __init__(self, role, port, peer_host=None, peer_port=None):
        self.role = role
        self.port = port
        self.peer_host = peer_host
        self.peer_port = peer_port
        wal_path = os.path.join(DATA_DIR, f"node_{port}.wal")
        self.mark_path = os.path.join(DATA_DIR, f"node_{port}.mark")
        self.sync_path = os.path.join(DATA_DIR, f"node_{port}.sync")
        self.state = KVState(wal_path)
        self.ack_index = -1
        self._write_lock = asyncio.Lock()
        self._recover()

    def _recover(self):
