        parts = line.split()
        if not parts:
            return "ERR"
        cmd = parts[0].upper()
        if cmd == "GET":
            return self._cmd_get(parts)
        if cmd == "SET":
            return await self._cmd_set(parts)
        if cmd == "DEL":
            return await self._cmd_del(parts)
        if cmd == "FLUSH":
            return await self._cmd_flush()
        if cmd == "REPLICATE":
            return self._cmd_replicate(parts)
        if cmd == "COMMIT":
            return self._cmd_commit(parts)
        if cmd == "PROMOTE":
            return await self._cmd_promote()
        if cmd == "STATUS":
            return self._cmd_status()
        return f"ERR unknown: {cmd}"

    def _cmd_get(self, parts):
        key = parts[1]
        value = self.state.get(key)
        return f"OK {value}" if value is not None else "NIL"

    async def _write_and_replicate(self, op, key, value=None):
        # Hold the lock from log-index allocation through replication.  Thus
        # concurrent client commands append WAL records in the same order in
        # which they are sent to the follower.
        async with self._write_lock:
            try:
                index = self.state.propose(op, key, value)
            except Exception:
                return "ERR_REPLICATE"

            if self.peer_port:
                replicated = await self._send_replicate(index, op, key, value)
                if not replicated:
                    return "ERR_REPLICATE"

            try:
                self.state.apply_through(index)
                self._persist_ack(index)
            except Exception:
                return "ERR_REPLICATE"
            return f"OK {index}"

    async def _cmd_set(self, parts):
        if self.role != "leader":
            return "ERR_NOT_LEADER"
        if len(parts) != 3:
            return "ERR usage: SET <key> <value>"
        return await self._write_and_replicate("SET", parts[1], parts[2])

    async def _cmd_del(self, parts):
        if self.role != "leader":
            return "ERR_NOT_LEADER"
        if len(parts) != 2:
            return "ERR usage: DEL <key>"
        return await self._write_and_replicate("DEL", parts[1])

    async def _cmd_flush(self):
        if self.role != "leader":
            return "ERR_NOT_LEADER"
        async with self._write_lock:
            last = self.state.wal.last_index
            if self.peer_port and last >= 0:
                committed = await self._send_commit(last)
                if not committed:
                    return "ERR_COMMIT"
            try:
                self.state.apply_through(last)
                self._persist_ack(last)
            except Exception:
                return "ERR_COMMIT"
            return f"OK {last}"

    def _cmd_replicate(self, parts):
        if len(parts) < 4:
            return "ERR_REPLICATE"
        try:
            index = int(parts[1])
        except ValueError:
            return "ERR_REPLICATE"
        op, key = parts[2], parts[3]
        value = parts[4] if len(parts) > 4 else None
        if op not in ("SET", "DEL"):
            return "ERR_REPLICATE"

        entry = {"op": op, "key": key}
        if value is not None:
            entry["value"] = value
        last = self.state.wal.last_index

        # Make retries after a lost response idempotent.
        if index <= last:
            if self.state.wal.entries[index] != entry:
                return "ERR_LOG_MISMATCH"
            try:
                self.state.apply_through(index)
                if self.ack_index < index:
                    self._persist_ack(index)
            except Exception:
                return "ERR_REPLICATE"
            return f"ACK {index}"

        if index != last + 1:
            return "ERR_LOG_GAP"

        try:
            appended = self.state.wal.append(entry)
            self.state.apply_through(appended)
            self._persist_ack(appended)
        except Exception:
            return "ERR_REPLICATE"
        return f"ACK {appended}"

    def _cmd_commit(self, parts):
        try:
            index = int(parts[1])
        except (IndexError, ValueError):
            return "ERR_COMMIT"
        if index < 0 or index > self.state.wal.last_index:
            return "ERR_COMMIT"
        if index > self.ack_index:
            try:
                self.state.apply_through(index)
                self._persist_ack(index)
            except Exception:
                return "ERR_COMMIT"
        return f"ACK {index}"

    async def _cmd_promote(self):
        async with self._write_lock:
            target = recovery.on_promote(self.state, self.ack_index)
            try:
                self._persist_ack(target)
            except Exception:
                return "ERR_PROMOTE"
            self.role = "leader"
            self.peer_host = None
            self.peer_port = None
            return "OK"

    def _cmd_status(self):
        return (f"role={self.role} "
                f"applied={self.state.applied_up_to} "
                f"wal_last={self.state.wal.last_index}")

