            reader, writer = await asyncio.wait_for(
                asyncio.open_connection(self.peer_host, self.peer_port), 5.0
            )
            command = f"REPLICATE {index} {op} {key}"
            if value is not None:
                command += f" {value}"
            writer.write((command + "\n").encode())
            await writer.drain()
            response = await asyncio.wait_for(reader.readline(), 5.0)
            fields = response.decode().strip().split()
            return len(fields) == 2 and fields[0] == "ACK" and fields[1] == str(index)
        except Exception:
            return False
        finally:
            if writer is not None:
                writer.close()
                try:
                    await writer.wait_closed()
                except Exception:
                    pass

    async def _send_commit(self, index):
        reader = writer = None
        try:
            reader, writer = await asyncio.wait_for(
                asyncio.open_connection(self.peer_host, self.peer_port), 5.0
            )
            writer.write((f"COMMIT {index}\n").encode())
            await writer.drain()
            response = await asyncio.wait_for(reader.readline(), 5.0)
            fields = response.decode().strip().split()
            return len(fields) == 2 and fields[0] == "ACK" and fields[1] == str(index)
        except Exception:
            return False
        finally:
            if writer is not None:
                writer.close()
                try:
                    await writer.wait_closed()
                except Exception:
                    pass

    async def run(self):
        server = await asyncio.start_server(self._handle, "0.0.0.0", self.port)
        async with server:
            await server.serve_forever()


def main():
    role = sys.argv[1]
    port = int(sys.argv[2])
    peer_host = sys.argv[3] if len(sys.argv) > 3 else None
    peer_port = int(sys.argv[4]) if len(sys.argv) > 4 else None
    node = ReplicatedKV(role, port, peer_host=peer_host, peer_port=peer_port)
    asyncio.run(node.run())


if __name__ == "__main__":
    main()
